# ---------------- APPLY EXPANSION ----------------
# Add the same conceptual coverage to English and Tamil, preserving all original
# blocks, figures, quizzes, navigation metadata and lesson order.  The patch is
# idempotent: blocks with the exact expansion titles are replaced, not duplicated.
lessons = {lesson['number']: lesson for unit in data['units'] for lesson in unit['lessons']}
assert set(lessons) == set(EXP), (set(lessons)-set(EXP), set(EXP)-set(lessons))

def block_title_set(entries, lang):
    return {e[f'{lang}_title'] for e in entries}

def insertion_index(blocks):
    for i,b in enumerate(blocks):
        if b.get('kind') in {'think_apply','summary'}:
            return i
    return len(blocks)

for num, entries in EXP.items():
    lesson = lessons[num]
    en_pairs = {(e['kind'], e['en_title']) for e in entries}
    ta_pairs = {(e['kind'], e['ta_title']) for e in entries}
    lesson['english'] = [b for b in lesson['english'] if (b.get('kind'), b.get('title')) not in en_pairs]
    lesson['tamil'] = [b for b in lesson['tamil'] if (b.get('kind'), b.get('title')) not in ta_pairs]
    en_blocks=[]; ta_blocks=[]
    for e in entries:
        if e['kind']=='table':
            en_blocks.append({'kind':'table','title':e['en_title'],'text':'','items':[],'rows':e['en_rows']})
            ta_blocks.append({'kind':'table','title':e['ta_title'],'text':'','items':[],'rows':e['ta_rows']})
        else:
            en_blocks.append({'kind':e['kind'],'title':e['en_title'],'text':e['en_text'],'items':[],'rows':[]})
            ta_blocks.append({'kind':e['kind'],'title':e['ta_title'],'text':e['ta_text'],'items':[],'rows':[]})
    ie=insertion_index(lesson['english']); it=insertion_index(lesson['tamil'])
    lesson['english'][ie:ie]=en_blocks
    lesson['tamil'][it:it]=ta_blocks

# Assertions: no lesson is left without new academic-depth content; EN/TA parity;
# no original lesson/quiz count change; and targeted food-chain ecosystem examples exist.
assert len(lessons)==46
for num,l in lessons.items():
    en_titles={b.get('title') for b in l['english']}
    ta_titles={b.get('title') for b in l['tamil']}
    assert block_title_set(EXP[num],'en') <= en_titles, num
    assert block_title_set(EXP[num],'ta') <= ta_titles, num

fc=lessons['2.2']
fc_text=' '.join(str(b) for b in fc['english'])
for required in ['Grassland','Pond','Marine','Forest','Mangrove / forest floor','detritus','energy pyramid']:
    assert required.lower() in fc_text.lower(), required

# Reject accidental Devanagari in Tamil content; English technical abbreviations are permitted.
tamil_text=' '.join(b.get('title','')+' '+b.get('text','') for l in lessons.values() for b in l['tamil'])
assert not re.search(r'[\u0900-\u097F]', tamil_text), 'Devanagari glyph found in Tamil lesson content'

out.write_text(json.dumps(data, ensure_ascii=False, indent=2)+'\n', encoding='utf-8')
